/*
 Problem: 4038. Count Integers Appearing in a Single Block
 Language: cpp
 Runtime: 7 ms (4.34%)
 Memory: 21.3 MB (21.40%)
 Tags: Array, Hash Table, Counting
*/
class Solution {
public:
    int countSpecialIntegers(vector<int>& nums) {
        int ans = 0;

        map<int, int> first, last, cnt;

        for (int i = 0; i < nums.size(); ++i) {
            if (!first.count(nums[i])) first[nums[i]] = i;
            last[nums[i]] = i;
            ++cnt[nums[i]];
        }

        for (const auto&[x, c] : cnt) {
            if (last[x] - first[x] + 1 == c) ++ans;
        }

        return ans;
    }
};
